/**
 * Finds exact pre-rendered audio by preset key or matching Bengali text
 */
export function getBengaliAudioUri(textOrKey: string): string | null {
  if (PRE_RENDERED_BENGALI_AUDIO[textOrKey]) {
    return PRE_RENDERED_BENGALI_AUDIO[textOrKey].dataUri;
  }
  const cleaned = textOrKey.trim();
  for (const entry of Object.values(PRE_RENDERED_BENGALI_AUDIO)) {
    if (entry.text === cleaned || cleaned.includes(entry.text) || entry.text.includes(cleaned)) {
      return entry.dataUri;
    }
  }
  return null;
}
